package ch.bbw.zork;/** * Author:  Michael Kolling, Version: 1.1, Date: August 2000 * refactoring: Rinaldo Lanza, September 2020 */public abstract class Room {    private String name;    private String description;	private int x;    private int y;    public Room(String name, String description, int x, int y) {        this.name = name;        this.description = description;        this.x = x;        this.y = y;    }    public String getName() {        return name;    }    public String getDescription() {        return description;    }    public int getX() {        return x;    }    public int getY() {        return y;    }}